#include "stdlib/math/base/special/expm1relf.h"
#include "stdlib/math/base/special/expm1f.h"
#include "stdlib/math/base/special/absf.h"
#include "stdlib/constants/float32/eps.h"
#include "stdlib/constants/float32/pinf.h"
#include "stdlib/constants/float32/max_ln.h"

static const float OVERFLOW_THRESHOLD = 93.25821685791016f;

/**
* Computes the relative error exponential of a single-precision floating-point number.
*
* ## Method
*
* To avoid overflow when \\( x \\) exceeds the natural logarithm of the maximum single-precision floating-point number, we can derive the following identity:
*
* ```tex
* \begin{align*}
* \frac{e^x - 1}{x} &= \frac{(e^{x/2} - 1)(e^{x/2} + 1)}{x} \\
*                   &= \frac{(e^{x/2} - 1)(e^{x/2} - 1 + 2)}{x} \\
*                   &= \frac{\operatorname{expm1}(x/2) \cdot (\operatorname{expm1}(x/2) + 2)}{x} \\
*                   &= \frac{\operatorname{expm1}(x/2)}{x} \cdot (\operatorname{expm1}(x/2) + 2)
* \end{align*}
* ```
*
* @param x    input value
* @return     output value
*
* @example
* float out = stdlib_base_expm1relf( 0.0f );
* // returns 1.0f
*/
float stdlib_base_expm1relf( const float x ) {
	float tmp;
	if ( stdlib_base_absf( x ) <= STDLIB_CONSTANT_FLOAT32_EPS ) {
		return 1.0f; // L'Hopital's Rule
	}
	if ( x < STDLIB_CONSTANT_FLOAT32_MAX_LN ) {
		return stdlib_base_expm1f( x ) / x;
	}
	if ( x >= OVERFLOW_THRESHOLD ) {
		return STDLIB_CONSTANT_FLOAT32_PINF; // L'Hopital's Rule
	}
	// MAX_LN <= x < OVERFLOW_THRESHOLD
	tmp = stdlib_base_expm1f( x/2.0f );
	return ( tmp/x ) * ( tmp+2.0f ); // note: we keep the `+2` term in order to prevent compiler optimizations from rearranging terms, even though `tmp + 2 = tmp` due to the limits of floating-point precision
}
